{{ (function(){
 var laput = haeMuistilaput.data || [];
 var CSS = "html,body{margin:0;height:100%;background:#F1EFE9;font-family:Inter,system-ui,-apple-system,sans-serif;overflow-y:auto}.seina{display:grid;grid-template-columns:repeat(auto-fill,minmax(215px,1fr));gap:20px;padding:18px}.lappu{position:relative;min-height:132px;padding:14px 14px 30px;border:1px solid rgba(0,0,0,.07);border-radius:3px;box-shadow:0 2px 7px rgba(0,0,0,.15);cursor:pointer;transition:transform .12s ease,box-shadow .12s ease}.lappu:hover{transform:rotate(0deg) scale(1.02)!important;box-shadow:0 7px 16px rgba(0,0,0,.22);z-index:2}.teksti{font-size:14px;line-height:1.45;color:#1F2937;white-space:pre-wrap;word-break:break-word}.meta{margin-top:10px;display:flex;gap:6px;flex-wrap:wrap}.pvm,.tp{font-size:11px;font-weight:600;background:rgba(255,255,255,.7);border:1px solid rgba(0,0,0,.08);border-radius:9999px;padding:2px 9px;color:#374151;line-height:1.5}.pvm.myohassa{background:#FEE2E2;color:#991B1B;border-color:#FCA5A5}.tp{color:#1D4ED8}.tp:hover{background:#DBEAFE}.jalki{position:absolute;left:14px;bottom:9px;font-size:11px;color:#6B7280}.pin{position:absolute;top:-9px;right:12px;font-size:17px;filter:drop-shadow(0 1px 1px rgba(0,0,0,.25))}.tyhja{grid-column:1/-1;padding:46px 20px;text-align:center;color:#6B7280;font-size:14px}";
 var JS = "document.addEventListener('click',function(e){var tp=e.target.closest('.tp');if(tp){parent.postMessage('tyo:'+tp.getAttribute('data-tyo')+'|'+Date.now(),'*');return;}var l=e.target.closest('.lappu');if(l){parent.postMessage('lappu:'+l.getAttribute('data-id')+'|'+Date.now(),'*');}});";
 function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
 var kulmat = [-1.3, 0.9, -0.5, 1.2, 0.4, -1.0];
 var kortit = laput.map(function(l, i){
  var meta = '';
  if (l.muistutus) { meta += '<span class="pvm' + (l.myohassa ? ' myohassa' : '') + '">' + esc(l.muistutus) + '</span>'; }
  if (l.tp_numero) { meta += '<span class="tp" data-tyo="' + esc(l.toimeksianto_id) + '">' + esc(l.tp_numero) + '</span>'; }
  return '<div class="lappu" data-id="' + esc(l.id) + '" style="background:' + esc(l.vari) + ';transform:rotate(' + kulmat[i % 6] + 'deg)">'
   + (l.kiinnitetty ? '<span class="pin">&#128204;</span>' : '')
   + '<div class="teksti">' + esc(l.teksti).replace(/\n/g, '<br>') + '</div>'
   + (meta ? '<div class="meta">' + meta + '</div>' : '')
   + '<div class="jalki">' + esc(l.tekija) + ' &middot; ' + esc(l.luotu_pvm) + '</div>'
   + '</div>';
 }).join('');
 if (!laput.length) { kortit = '<div class="tyhja">Ei muistilappuja. Lisää ensimmäinen &rdquo;+ Uusi lappu&rdquo; -painikkeesta.</div>'; }
 return '<html><head><meta charset="utf-8"><style>' + CSS + '</style></head><body><div class="seina">' + kortit + '</div><script>' + JS + '<\/script></body></html>';
})() }}
